// Generate unique request ID and check for duplicates
const request_id = 'req-' + Math.random().toString(36).substring(2, 15);
const job_id = $json.job_id || 'auto-' + Date.now();
const timestamp = new Date().toISOString();

return [
  {
    json: {
      request_id,
      job_id,
      submitted_at: timestamp,
      ...($json),
      shortlist_size: $json.shortlist_size || 10,
      outreach_enabled: $json.outreach_enabled !== false
    }
  }
];

// Merge and normalize candidates from Drive and Sheets
const driveResumes = $input.fromInput('list-resumes-drive');
const sheetCandidates = $input.fromInput('read-candidate-registry');

const candidates = [];
const seen = new Set();

// Add from Sheets
sheetCandidates.forEach((row) => {
  if (row.email && !seen.has(row.email)) {
    candidates.push({
      candidate_id: row.id || `cand-${row.email.split('@')[0]}`,
      name: row.name || 'Unknown',
      email: row.email,
      phone: row.phone || null,
      skills: (row.skills || '').split(',').map(s => s.trim()).filter(s => s),
      years_experience: row.years_experience || 0,
      current_title: row.current_title || null,
      current_company: row.current_company || null,
      location: row.location || null,
      resume_drive_file_id: row.resume_drive_file_id || null,
      source: 'sheets',
      created_at: row.created_at || new Date().toISOString()
    });
    seen.add(row.email);
  }
});

// Add from Drive (filter PDFs)
driveResumes.forEach((file) => {
  if (file.mimeType === 'application/pdf' && !seen.has(file.id)) {
    const nameWithoutExt = file.name.replace('.pdf', '');
    candidates.push({
      candidate_id: `cand-drive-${file.id}`,
      name: nameWithoutExt,
      email: null,
      phone: null,
      skills: [],
      years_experience: 0,
      current_title: null,
      current_company: null,
      location: null,
      resume_drive_file_id: file.id,
      source: 'drive',
      created_at: file.createdTime || new Date().toISOString()
    });
    seen.add(file.id);
  }
});

return [{ json: { candidates, total: candidates.length } }];

