// Simulate outreach and compute interest score
// In production, this would wait for webhook callback or timeout
// For demo: use Gemini to simulate interest response

const interest_signals = {
  responded: true,
  positive_sentiment: 0.85,
  availability: 0.9,
  compensation_aligned: 0.75,
  engagement_depth: 0.8
};

const interest_score = Math.round(
  (interest_signals.positive_sentiment * 0.35 +
   interest_signals.availability * 0.25 +
   interest_signals.compensation_aligned * 0.20 +
   interest_signals.engagement_depth * 0.20) * 100
);

return [
  {
    json: {
      ...($json),
      interest_score,
      interest_signals,
      outreach_conducted: true,
      conversation_summary: 'Positive response with interest in learning more'
    }
  }
];

// No outreach: use baseline interest score
const interest_score = 50; // Neutral baseline

return [
  {
    json: {
      ...($json),
      interest_score,
      interest_signals: null,
      outreach_conducted: false,
      conversation_summary: 'No outreach conducted'
    }
  }
];

// Compute composite score and rank
const match_score = $json.match_score || 50;
const interest_score = $json.interest_score || 50;
const composite_score = Math.round(match_score * 0.70 + interest_score * 0.30);

let status_label = 'Requires Review';
if (composite_score >= 80) status_label = 'Strong Fit';
else if (composite_score >= 65) status_label = 'Good Fit';
else if (composite_score >= 50) status_label = 'Watchlist';

return [
  {
    json: {
      ...($json),
      composite_score,
      status_label,
      confidence: $json.confidence || 0.75
    }
  }
];

// Accumulate results from batched processing
const results = [];

// Collect all processed candidates
$input.all().forEach((item) => {
  if (item.json.composite_score !== undefined) {
    results.push(item.json);
  }
});

// Sort by composite_score DESC, then match_score DESC, then interest_score DESC
results.sort((a, b) => {
  if (b.composite_score !== a.composite_score) return b.composite_score - a.composite_score;
  if (b.match_score !== a.match_score) return b.match_score - a.match_score;
  if (b.interest_score !== a.interest_score) return b.interest_score - a.interest_score;
  if (b.years_experience !== a.years_experience) return b.years_experience - a.years_experience;
  return 0;
});

// Add rank and limit to shortlist_size
const shortlist_size = $input.first().json.shortlist_size || 10;
const shortlist = results.slice(0, shortlist_size).map((candidate, idx) => ({
  ...candidate,
  rank: idx + 1
}));

return [
  {
    json: {
      status: 'completed',
      job_id: $input.first().json.job_id,
      request_id: $input.first().json.request_id,
      timestamp: new Date().toISOString(),
      candidates_evaluated: results.length,
      candidates_returned: shortlist.length,
      shortlist
    }
  }
];
